const $=s=>document.querySelector(s);
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function copy(text,button){try{await navigator.clipboard.writeText(text);const old=button.textContent;button.textContent='Copied ✓';setTimeout(()=>button.textContent=old,2000);}catch{$('#copy-status').textContent='Clipboard unavailable. Select and copy the displayed text.';}}
async function start(){try{const [tokens,assets,sources]=await Promise.all(['tokens','assets','sources'].map(n=>fetch(`v1/${n}.json?v=0.2.0`).then(r=>{if(!r.ok)throw Error('Unavailable data');return r.json();})));
$('#swatches').innerHTML=Object.entries(tokens.colors).map(([n,c])=>`<div class="swatch"><div class="swatch-color" style="background:${c.value};color:${['blue','ink','muted'].includes(n)?'#FFFFFF':'#151435'}">${escape(n.charAt(0).toUpperCase()+n.slice(1))}</div><div class="swatch-body"><button data-color="${c.value}" aria-label="Copy ${n} colour ${c.value}">${c.value} <span aria-hidden="true">↗</span></button><p>${escape(c.recommendedUse)}</p></div></div>`).join('');
$('#swatches').addEventListener('click',e=>{const b=e.target.closest('button');if(b)copy(b.dataset.color,b);});
$('#asset-list').innerHTML=assets.map(a=>`<article class="asset-card"><div class="asset-preview ${a.id==='white-logo'?'dark':''}"><img src="${escape(a.pngs[2].url)}" alt="${escape(a.title)}" loading="lazy"></div><div class="asset-info"><h3>${escape(a.title)}</h3><p>${a.id==='white-logo'?'White logo · use on blue or dark surfaces.':'Original blue artwork · use on white or cream surfaces.'}</p><div class="asset-sizes">${a.pngs.map(p=>`<a href="${escape(p.url)}" download>${p.width}px PNG ↓</a>`).join('')}</div><a class="original-link" href="${escape(a.localSvg)}" download>Original SVG ↓</a><a class="original-link" href="${escape(a.url)}">Source ↗</a></div></article>`).join('');
const renderSources=()=>{const q=$('#search').value.toLowerCase();const found=sources.filter(s=>Object.values(s).join(' ').toLowerCase().includes(q));$('#source-list').innerHTML=found.map(s=>`<div class="source-row"><div><h3><a href="${escape(s.url)}">${escape(s.title)} ↗</a></h3><small>${escape(s.status)}</small></div><p>${escape(s.use)}</p></div>`).join('');$('#no-results').hidden=!!found.length;};renderSources();$('#search').addEventListener('input',renderSources);
}catch{$('#source-list').textContent='Reference data could not load. Open the downloadable brief for the full source list.';}}
$('#copy-prompt').addEventListener('click',e=>copy(`Use the read-only MCP at ${location.origin}/mcp. Read its brand system, UI guidance and asset catalogue before building. Static fallback: ${location.origin}/llms.txt and ${location.origin}/brand-brief.md. Follow exact observed WaterAid tokens and proposed Wetland UI conventions. Use catalogue PNG/SVG URLs, preserve aspect ratios, and select white logos for dark backgrounds and blue icons for light backgrounds. Keep official guidance, observed styling and proposals distinct. Do not infer asset permission or WaterAid endorsement. Keep fictional challenge data separate. Return completed work with sources.`,e.target));
$('#download-slides').addEventListener('click',()=>{const a=document.createElement('a');a.href='slide-starter.html';a.download='wetland-slide-starter.html';a.click();});
const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash===`#${e.target.id}`));}},{rootMargin:'-10% 0px -65% 0px'});document.querySelectorAll('main section').forEach(s=>observer.observe(s));start();
$('#copy-mcp').addEventListener('click',e=>copy('https://wateraid-brand-hub-462504004653.northamerica-northeast2.run.app/mcp',e.target));
$('#test-mcp').addEventListener('click',async e=>{const button=e.target;button.disabled=true;$('#mcp-status').textContent='Checking MCP connection…';try{const r=await fetch('/mcp',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json, text/event-stream'},body:JSON.stringify({jsonrpc:'2.0',id:1,method:'tools/list',params:{}})});if(!r.ok)throw Error('MCP returned '+r.status);const data=await r.json();const names=data.result?.tools?.map(t=>t.name)||[];if(!['get_brand_system','list_assets','get_asset','get_ui_guidance','get_document_guidance'].every(n=>names.includes(n)))throw Error('Tool list incomplete');$('#mcp-status').textContent='Connected · all 5 read-only brand tools are ready.';}catch(error){$('#mcp-status').textContent='Connection check failed. Please retry after the service has updated.';}finally{button.disabled=false;}});
